   row={'id':('cf' if species=='drifella' else 'cl')+cat+str(i+1).zfill(2),'label':label,'source':sources[cat],'sourceUrls':URLs,'design':f'{label}: independently sculpted, fitted {species} component; shared rest-pose rig.', 'batch':4}
